{
["autorun"] = true,
["name"] = "Format Decimal",
["code"] = "local F = Cell.funcs\n\nfunction F.FormatNumber(n)\n    if math.abs(n) >= 1e9 then\n        return string.format(\"%.1fB\", n / 1e9):gsub(\"%.0\", \"\")\n    elseif math.abs(n) >= 1e6 then\n        return string.format(\"%.1fM\", n / 1e6):gsub(\"%.0\", \"\")\n    elseif math.abs(n) >= 1e3 then\n        return string.format(\"%dK\", n / 1e3)\n    else\n        return tostring(n)\n    end\nend",
},
{
["autorun"] = true,
["name"] = "Bnet Nicknames",
["code"] = "local F = Cell.funcs\n\nfunction F.GetNickname(shortname, fullname)\n    local name\n    \n    if Cell.vars.nicknameCustomEnabled then\n        if shortname and UnitGUID(shortname) then\n            local friend = C_BattleNet.GetAccountInfoByGUID(UnitGUID(shortname))\n            if friend and friend.battleTag then\n                name = Cell.vars.nicknameCustoms[friend.battleTag] or \n                Cell.vars.nicknames[friend.battleTag]\n            end\n        end\n        \n        if not name then\n            name = Cell.vars.nicknameCustoms[fullname] or\n            Cell.vars.nicknameCustoms[shortname] or\n            Cell.vars.nicknames[fullname] or\n            Cell.vars.nicknames[shortname] or\n            shortname\n        end\n    else\n        name = Cell.vars.nicknames[fullname] or\n        Cell.vars.nicknames[shortname] or\n        shortname\n    end\n    \n    return name or _G.UNKNOWNOBJECT\nend",
},
{
["autorun"] = true,
["name"] = "UF Buff Glow",
["code"] = "-- apply glow to cuf player buffs\n\nlocal spellIdTable = {\n    [2825] = true, -- Lust\n    [32182] = true, -- Heroism\n    [80353] = true, -- Time Warp\n    [90355] = true, -- Ancient Hysteria\n    [390386] = true, -- Fury of the Aspects\n    [264667] = true, -- Primal Rage\n    [444257] = true, -- Thunderous Drums\n    [160452] = true, -- Netherwinds\n    \n    [10060] = true, -- Power Infusion\n    [406789] = true, -- Spatial Paradox\n    \n    [1022] = true, -- Blessing of Protection\n    [204018] = true, -- Blessing of Spellwarding\n    [6940] = true, -- Blessing of Sacrifice\n    [33206] = true, -- Pain Suppression\n    [47788] = true, -- Guardian Spirit\n    [62618] = true, -- PW: Barrier\n    [116849] = true, -- Life Cocoon\n    [102342] = true, -- Ironbark\n    [357170] = true, -- Time Dilation\n    \n    [325174] = true, -- Spirit Link\n    [97463] = true, -- Rallying Cry\n    [145629] = true, -- Anti-Magic Zone\n    [265144] = true, -- Symbol of Hope\n    \n    [108281] = true, -- Ancestral Guidance\n    [124974] = true, -- Nature's Vigil\n    [15286] = true, -- Vampiric Embrace\n    \n    [444959] = true, -- Spymaster's Web\n    [444282] = true, -- Creeping Coagulum\n    [457533] = true, -- Evasive Maneuvers\n}\n\nlocal function AuraGlow()\n    -- Make sure CUF is actually loaded\n    local CUF = _G[\"CUF\"]\n    if not CUF then return end\n    \n    local Util = CUF.Util\n    \n    local function PostUpdate(icon, auraData)\n        if spellIdTable[auraData.spellId] then\n            Util.GlowStart_Pixel(icon)\n        else\n            Util.GlowStop(icon)\n        end\n    end\n    \n    -- Override PostUpdate for all auras\n    Util:IterateAllUnitButtons(function(button, unit)\n            if not button:HasWidget(\"buffs\") then return end\n            \n            if unit ~= \"player\" then return end\n            \n            for _, icon in ipairs(button.widgets.buffs) do\n                icon.PostUpdate = PostUpdate\n            end\n    end)\nend\nCell.RegisterCallback(\"CUF_FramesInitialized\", \"Snippet_AuraGlow\", AuraGlow)\n\n\n",
},
{
["autorun"] = true,
["name"] = "Power Bar Color",
["code"] = "-- Function to change the power bar default mana color to #27c3fb\n-- and change the background color of power bar to the background of cell frames\n-- instead of 20% darker than the original power bar color\n\nlocal F = Cell.funcs\n\nfunction F.GetPowerColor(unit)\n    local r, g, b, t\n    -- https://wow.gamepedia.com/API_UnitPowerType\n    local powerType, powerToken, altR, altG, altB = UnitPowerType(unit)\n    t = powerType\n    \n    local info = PowerBarColor[powerToken]\n    if powerType == 0 then -- MANA\n        info = {r=0.1529, g=0.7647, b=0.9843} -- default mana color is too dark! #27c3fb\n    elseif powerType == 3 then -- ENERGY\n        info = {r=1, g = 0.9333, b=0.3725} -- default is too bright! #ffee5f\n    elseif powerType == 13 then -- INSANITY\n        info = {r=0.6, g=0.2, b=1}\n    end\n    \n    if info then\n        --The PowerBarColor takes priority\n        r, g, b = info.r, info.g, info.b\n    else\n        if not altR then\n            -- Couldn't find a power token entry. Default to indexing by power type or just mana if  we don't have that either.\n            info = PowerBarColor[powerType] or PowerBarColor[\"MANA\"]\n            r, g, b = info.r, info.g, info.b\n        else\n            r, g, b = altR, altG, altB\n        end\n    end\n    return r, g, b, t\nend\n\nfunction F.GetPowerBarColor(unit, class)\n    local r, g, b, lossR, lossG, lossB, t\n    r, g, b, t = F.GetPowerColor(unit)\n    \n    if not Cell.loaded then\n        return r, g, b, r*0.2, g*0.2, b*0.2, t\n    end\n    \n    if CellDB[\"appearance\"][\"powerColor\"][1] == \"power_color_dark\" then\n        lossR, lossG, lossB = r, g, b\n    elseif CellDB[\"appearance\"][\"powerColor\"][1] == \"class_color\" then\n        r, g, b = F:GetClassColor(class)\n    elseif CellDB[\"appearance\"][\"powerColor\"][1] == \"custom\" then\n        r, g, b = unpack(CellDB[\"appearance\"][\"powerColor\"][2])\n    end\n    \n    lossR = CellDB[\"appearance\"][\"barColor\"][2][1]\n    lossG = CellDB[\"appearance\"][\"barColor\"][2][2]\n    lossB = CellDB[\"appearance\"][\"barColor\"][2][3]\n    \n    return r, g, b, lossR, lossG, lossB, t\nend",
},
{
["autorun"] = true,
["name"] = "Lotus Infusion vs. Chi Harmony Enable",
["code"] = "-- this snippet enables/disables color indicators:\n-- disables chi harmony if lotus infusion is talented, enables lotis infusion\n-- or disables lotus infusion indicator if chi harmony is talented, enables chi harmony\n\nlocal chiHarmonyIndicator = \"indicator1\"\nlocal lotusInfusionIndicator = \"indicator2\"\nlocal chiHarmonyId = 448392\nlocal lotusInfusionId = 458431\n\nlocal function IndicatorSwap()\n    \n    local spec = GetSpecializationInfo(GetSpecialization())\n    if spec ~= 270 then return end -- check for mistweaver\n    \n    if string.find(Cell.vars.currentLayout, \"M%+\") then return end -- don't continue for m+ layout\n    \n    local hasChiHarmony = IsPlayerSpell(chiHarmonyId)\n    local hasLotusInfusion = IsPlayerSpell(lotusInfusionId)\n    \n    -- update indicators based on talent\n    Cell.snippetVars.enabledIndicators[chiHarmonyIndicator] = hasChiHarmony or nil\n    Cell.snippetVars.enabledIndicators[lotusInfusionIndicator] = hasLotusInfusion or nil\nend\n\nlocal eventFrame = CreateFrame(\"Frame\")\neventFrame:RegisterEvent(\"PLAYER_ENTERING_WORLD\")\neventFrame:RegisterEvent(\"TRAIT_CONFIG_UPDATED\")\n\neventFrame:SetScript(\"OnEvent\", function(self, event)\n        IndicatorSwap()\nend)",
},
